// 36-locale reference data for English Prepositions (9 semantic groups, 175 items)

const LOCS = [
  'ar', 'bn', 'bg', 'zh', 'hr', 'cs', 'da', 'en', 'et', 'fi', 'fr', 'de',
  'el', 'hi', 'hu', 'id', 'it', 'ja', 'kk', 'ko', 'lv', 'lt', 'fa', 'pl',
  'pt', 'ro', 'ru', 'sk', 'sl', 'es', 'sv', 'th', 'tr', 'uk', 'ur', 'vi',
];

function t36(vals) {
  const out = {};
  for (let i = 0; i < LOCS.length; i++) {
    out[LOCS[i]] = vals[i];
  }
  return out;
}

function item(word, vals, example) {
  return { word, tr: t36(vals), example };
}

