    "en": "Marks a deadline (\"no later than\"). Unlike until (continuous state up to a time), by focuses on completion before the limit.",
    "uk": "Позначає дедлайн («не пізніше цього моменту»). На відміну від until (дія триває до моменту), by вказує на завершення до строку.",
