    "da": "Udtrykker lighed (”som / ligesom”). Til en faktisk rolle eller job bruges as.",
    "lv": "Izsaka līdzību (“kā / līdzīgi”). Reālai lomai vai profesijai lieto as.",
    "lt": "Reiškia panašumą („kaip / panašiai“). Tikram vaidmeniui ar profesijai vartokite as.",
    "sk": "Vyjadruje podobnosť („ako“). Pre skutočnú rolu alebo povolanie použite as.",
