    "fi": "Ilmaisee samankaltaisuutta (”kuin”). Todelliseen rooliin tai ammattiin käytetään sanaa as.",
    "hr": "Izražava sličnost („kao“). Za stvarnu ulogu ili zanimanje koristite as.",
    "cs": "Vyjadřuje podobnost („jako“). Pro skutečnou roli nebo povolání použijte as.",
    "sv": "Uttrycker likhet (”som / liksom”). För en verklig roll eller ett yrke används as.",
    "et": "Väljendab sarnasust („nagu“). Tegeliku rolli või ameti puhul kasuta as.",
    "hi": "समानता या तुलना दर्शाता है (“की तरह”)। वास्तविक पद या भूमिका के लिए as प्रयोग करें।",
    "bn": "সাদৃশ্য বা তুলনা বোঝায় (“মতো”)। প্রকৃত পেশা বা ভূমিকার জন্য as ব্যবহার করুন।",
    "ar": "يعبّر عن التشبيه والمماثلة («مثل»). أما للوظيفة أو الدور الفعلي فنستخدم as.",
