    "ur": "مشابہت یا موازنہ بتاتا ہے (“کی طرح”)۔ اصل پیشے یا کردار کے لیے as استعمال کریں۔",
    "id": "Menyatakan kemiripan (“seperti”). Untuk peran atau profesi nyata, gunakan as.",
    "vi": "Diễn tả sự giống nhau/so sánh (“như là”). Với vai trò hoặc nghề nghiệp thực sự, dùng as.",
    "th": "ใช้เปรียบเทียบความคล้ายคลึง (“เหมือน”) แต่ถ้าเป็นบทบาทหรืออาชีพจริงให้ใช้ as",
