for (const _grp of PREPOSITIONS_GROUPS) {
  if (!_grp || !Array.isArray(_grp.items)) continue;
  for (const _it of _grp.items) {
    const _note = PREPOSITION_USAGE_NOTES[`${_grp.id}|${_it.word}`];
    if (_note && !_it.note) {
      _it.note = _note;
    }
  }
}
